import React, { useEffect, useState } from "react";
import Navbar from "./components/Navbar";
import UserForm from "./components/UserForm";
import UserCard from "./components/UserCard";
import RunList from "./components/RunList";
import * as api from "./utils/api";
import { motion, AnimatePresence } from "framer-motion";

export default function App() {
  const [users, setUsers] = useState([]);
  const [selectedUserId, setSelectedUserId] = useState("");
  const [runs, setRuns] = useState([]);
  const [loading, setLoading] = useState(false);

  async function refreshUsers() {
    setLoading(true);
    const { ok, body } = await api.listUsers();
    if (ok && body) setUsers(body.users || []);
    setLoading(false);
  }

  useEffect(() => {
    refreshUsers();
  }, []);

  async function handleCreateUser(payload) {
    const { ok } = await api.createUser(payload);
    if (ok) {
      refreshUsers();
    } else {
      alert("Failed to create user. Make sure age is a number.");
    }
  }

  async function handleDeleteUser(id) {
    if (!window.confirm("Delete user and all runs?")) return;
    const { ok } = await api.deleteUser(id);
    if (ok) {
      if (id === selectedUserId) {
        setSelectedUserId("");
        setRuns([]);
      }
      refreshUsers();
    } else {
      alert("User not found.");
    }
  }

  async function handleSelectUser(id) {
    setSelectedUserId(id);
    const { ok, body } = await api.listRuns(id);
    if (ok && body) setRuns(body.runs || []);
    else setRuns([]);
  }

  async function handleAddRun(payload) {
    if (!selectedUserId) return alert("Select a user first.");
    const { ok } = await api.addRun(selectedUserId, payload);
    if (ok) {
      // refresh runs
      const { ok: ok2, body } = await api.listRuns(selectedUserId);
      if (ok2 && body) setRuns(body.runs || []);
    } else {
      alert("Failed to add run. Check inputs.");
    }
  }

  return (
    <div className="app-root">
      <Navbar />
      <main className="container">
        <section className="left-col">
          <motion.div layout className="panel">
            <UserForm onCreate={handleCreateUser} />
            <div className="spacer" />
            <div className="card">
              <div className="card-header">Runners</div>
              <div className="card-body users-grid">
                {loading ? (
                  <div className="muted">Loading...</div>
                ) : users.length === 0 ? (
                  <div className="muted">No users yet. Add someone.</div>
                ) : (
                  <AnimatePresence>
                    {users.map((u) => (
                      <motion.div
                        key={u.id}
                        initial={{ opacity: 0, y: 6 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -6 }}
                      >
                        <UserCard
                          user={u}
                          isSelected={u.id === selectedUserId}
                          onSelect={handleSelectUser}
                          onDelete={handleDeleteUser}
                        />
                      </motion.div>
                    ))}
                  </AnimatePresence>
                )}
              </div>
              <div className="card-footer">
                <button className="ghost" onClick={refreshUsers}>Refresh</button>
              </div>
            </div>
          </motion.div>
        </section>

        <section className="right-col">
          <motion.div layout className="panel">
            {selectedUserId ? (
              <RunList runs={runs} onAddRun={handleAddRun} />
            ) : (
              <div className="card empty-card">
                <div className="card-body">
                  <h3 className="muted">Select a user to view/add runs</h3>
                  <p className="muted small">Choose a runner from the left panel to manage their runs.</p>
                </div>
              </div>
            )}
          </motion.div>
        </section>
      </main>
      <footer className="footer">Made with ❤️ — Run Run Run</footer>
    </div>
  );
}
